insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_J_CHEM_LANG','J_CHEM_LANG','化学用语与物质变化','化学用语要同时说清“是什么”和“有多少”。','先区分宏观物质、微观粒子和化学符号，再判断变化中是否生成新物质。','["圈出对象","翻译符号含义","用新物质生成与否判断变化"]'::jsonb,'["把状态改变当成化学变化","把元素符号和物质化学式混用"]'::jsonb,'冰融化没有新物质生成，属于物理变化。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
