insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_J_EXPERIMENT','J_EXPERIMENT','化学实验基本操作','安全、规范和误差方向是实验题的三条主线。','操作题先判断目的，再检查仪器、顺序和读数方法。','["明确实验目的","检查安全与气密性","判断错误造成的结果方向"]'::jsonb,'["把“看起来合理”当成规范操作","只报错不分析误差方向"]'::jsonb,'量筒读数时视线应与液体凹液面最低处相平。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
