insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_J09_ATOM_06','M4W_J09_ATOM_6','J09_ATOM',3,'初三','处理“原子结构与元素”问题时，最可靠的第一步是','["读出质子数和电子数","用中子数判断元素种类","先猜答案再补理由","忽略题设条件直接套公式"]'::jsonb,0,'第一步应先读出质子数和电子数，之后才能稳定迁移。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
