insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H1_CLASSIFY','H1_CLASSIFY','物质的分类与分散系','分类标准不同，分类结果可以交叉，但同一次判断必须坚持同一标准。','从组成、分散质粒径、在水中电离情况和氧化物性质四条线建立分类树。','["先写分类标准","再看组成或性质","最后检查是否偷换标准"]'::jsonb,'["把溶液当成纯净物","把能导电的物质都叫电解质"]'::jsonb,'Na₂O由两种元素组成且含氧，是碱性氧化物。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
