insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H1_PERIODIC','H1_PERIODIC','元素周期律','位置反映结构，结构决定性质，比较时必须限定同周期或同主族。','围绕原子半径、金属性、非金属性、最高价氧化物水化物酸碱性建立因果链。','["由位置写电子层和价电子","选择同周期或同主族规律","用事实验证结论"]'::jsonb,'["跨周期机械比较半径","用最高正价规律套F和O"]'::jsonb,'同周期从左到右核电荷增大，原子半径总体减小。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
