insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H1_REDOX','H1_REDOX','氧化还原反应','化合价升降、电子得失和氧化还原身份必须成套对应。','用价态变化定位变价元素，再用电子守恒处理配平和定量关系。','["标化合价","连升降线","按电子守恒配平","检查原子与电荷守恒"]'::jsonb,'["把氧化剂和氧化产物混淆","只守恒原子不守恒电子"]'::jsonb,'Fe²⁺→Fe³⁺失1e⁻，Fe²⁺是还原剂。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
