insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_REDOX_02','M4W_H1_REDOX_2','H1_REDOX',2,'高一','Fe²⁺转化为Fe³⁺时发生','["得到1个电子","失去1个电子","得到2个电子","化合价降低"]'::jsonb,1,'化合价升高1，失去1个电子。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_REDOX_03','M4W_H1_REDOX_3','H1_REDOX',2,'高一','下列反应一定属于氧化还原反应的是','["复分解反应","有单质参加的化合反应","中和反应","沉淀反应"]'::jsonb,1,'有单质参加且生成化合物时必有化合价变化。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
