insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_REDOX_05','M4W_H1_REDOX_5','H1_REDOX',3,'高一','关于“氧化还原反应”的核心规律，下列说法正确的是','["化合价升降、电子得失和氧化还原身份必须成套对应。","把氧化剂和氧化产物混淆","只守恒原子不守恒电子","题目条件不会影响判断"]'::jsonb,0,'该模块的核心规律是：化合价升降、电子得失和氧化还原身份必须成套对应。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_REDOX_06','M4W_H1_REDOX_6','H1_REDOX',3,'高一','处理“氧化还原反应”问题时，最可靠的第一步是','["标化合价","把氧化剂和氧化产物混淆","先猜答案再补理由","忽略题设条件直接套公式"]'::jsonb,0,'第一步应先标化合价，之后才能稳定迁移。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
