insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H1_ELECTROLYTE','H1_ELECTROLYTE','电解质与离子反应','离子方程式先拆强电解质，再用电荷、原子和反应事实三重检查。','把电解质判断、离子共存、离子方程式和少量过量问题连成一条主线。','["写分子方程式","拆可溶强电解质","删旁观离子","三重守恒检查"]'::jsonb,'["弱酸弱碱错误拆分","忽略少量过量与反应顺序"]'::jsonb,'HCl与NaOH反应的本质是H⁺+OH⁻=H₂O。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
