insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_ELECTROLYTE_02','M4W_H1_ELECTROLYTE_2','H1_ELECTROLYTE',2,'高一','强酸与强碱溶液反应的离子方程式通常是','["H⁺+OH⁻=H₂O","HCl+NaOH=NaCl+H₂O","2H₂+O₂=2H₂O","Na⁺+Cl⁻=NaCl"]'::jsonb,0,'旁观离子删去后保留H⁺与OH⁻反应。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
