insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H1_MOLE','H1_MOLE','物质的量及相关计算','所有计量都先回到n，再从n走向质量、粒子数、气体体积或浓度。','用n=m/M、N=nNₐ、V=nVₘ、c=n/V建立统一换算网络，并重视单位和条件。','["圈出已知量与单位","换算成物质的量","按计量关系转移","回到所求量并验数量级"]'::jsonb,'["把气体摩尔体积用于任意条件","溶液体积使用mL却不换L"]'::jsonb,'18 g H₂O为1 mol，含约6.02×10²³个水分子。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
