insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H1_MOLE_06','M4W_H1_MOLE_6','H1_MOLE',3,'高一','处理“物质的量及相关计算”问题时，最可靠的第一步是','["圈出已知量与单位","把气体摩尔体积用于任意条件","先猜答案再补理由","忽略题设条件直接套公式"]'::jsonb,0,'第一步应先圈出已知量与单位，之后才能稳定迁移。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_skills(id,title,module_id,grade_band,max_level,exam_importance,exam_depth,prerequisites,level_criteria,active) values('H1_NACL','钠、氯及其化合物','H1-F06','高一',6,4,5,array[]::text[],'[{"level":1,"studentFacingGoal":"钠、氯及其化合物 L1","requiredAbility":"能识别并解释基础概念"},{"level":2,"studentFacingGoal":"钠、氯及其化合物 L2","requiredAbility":"能识别并解释基础概念"},{"level":3,"studentFacingGoal":"钠、氯及其化合物 L3","requiredAbility":"能在变化情境中迁移"},{"level":4,"studentFacingGoal":"钠、氯及其化合物 L4","requiredAbility":"能在变化情境中迁移"},{"level":5,"studentFacingGoal":"钠、氯及其化合物 L5","requiredAbility":"能在变化情境中迁移"},{"level":6,"studentFacingGoal":"钠、氯及其化合物 L6","requiredAbility":"能完成综合推理与检验"}]'::jsonb,true) on conflict(id) do update set title=excluded.title,module_id=excluded.module_id,grade_band=excluded.grade_band,max_level=excluded.max_level,exam_importance=excluded.exam_importance,exam_depth=excluded.exam_depth,level_criteria=excluded.level_criteria,active=true,updated_at=now();
insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H1_NACL','H1_NACL','钠、氯及其化合物','元素化合物学习要用“价态—类别—反应条件”组织，不背孤立方程式。','以Na、Na₂O₂、Na₂CO₃、Cl₂、HClO和含氯消毒剂为核心建立转化网。','["判断中心元素价态","识别物质类别","结合条件预测产物","用守恒写方程式"]'::jsonb,'["忽略氯水多种成分","把Na₂O₂中的O写成-2价"]'::jsonb,'Cl₂与水反应生成HCl和HClO，HClO具有强氧化性。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
