insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H2_THERMO','H2_THERMO','化学反应与能量','焓变正负说明系统吸放热，盖斯定律按反应式线性组合。','把热化学方程式、反应热计算、键能估算和盖斯定律统一到能量守恒。','["核对物态和计量数","判断反应式倍乘或倒转","同步处理ΔH","检查正负与单位"]'::jsonb,'["反应式加倍却不加倍ΔH","忽略物质聚集状态"]'::jsonb,'反应式整体乘2，ΔH也乘2。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
