insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H2_RATE','H2_RATE','化学反应速率与影响因素','速率比较必须统一物质、时间和化学计量数。','从浓度、温度、压强、催化剂和有效碰撞解释速率变化。','["写清速率表示物质","统一时间与单位","用计量数换算","解释微观原因"]'::jsonb,'["把平衡移动当成速率变化","用不同物质速率直接比较"]'::jsonb,'对aA→bB，有v(A)/a=v(B)/b。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H2_RATE_01','M4W_H2_RATE_1','H2_RATE',2,'高二','升高温度通常使反应速率增大，主要因为','["活化能降低","活化分子百分数增大","平衡常数一定增大","反应物浓度一定增大"]'::jsonb,1,'更多分子具有足够能量发生有效碰撞。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H2_RATE_02','M4W_H2_RATE_2','H2_RATE',2,'高二','催化剂加快反应速率的本质是','["提高反应热","降低反应途径的活化能","增大平衡常数","改变反应物浓度"]'::jsonb,1,'催化剂提供较低活化能的反应途径。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H2_RATE_03','M4W_H2_RATE_3','H2_RATE',2,'高二','对N₂+3H₂⇌2NH₃，若v(N₂)=0.2 mol·L⁻¹·s⁻¹，则v(H₂)为','["0.2","0.4","0.6","1.0"]'::jsonb,2,'速率之比等于化学计量数之比1∶3。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H2_RATE_04','M4W_H2_RATE_4','H2_RATE',2,'高二','恒容容器中加入惰性气体，对气相反应速率的直接影响通常是','["一定增大","一定减小","各反应物浓度不变，速率基本不变","平衡常数改变"]'::jsonb,2,'恒容时反应物浓度不变。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H2_RATE_05','M4W_H2_RATE_5','H2_RATE',3,'高二','关于“化学反应速率与影响因素”的核心规律，下列说法正确的是','["速率比较必须统一物质、时间和化学计量数。","把平衡移动当成速率变化","用不同物质速率直接比较","题目条件不会影响判断"]'::jsonb,0,'该模块的核心规律是：速率比较必须统一物质、时间和化学计量数。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H2_RATE_06','M4W_H2_RATE_6','H2_RATE',3,'高二','处理“化学反应速率与影响因素”问题时，最可靠的第一步是','["写清速率表示物质","把平衡移动当成速率变化","先猜答案再补理由","忽略题设条件直接套公式"]'::jsonb,0,'第一步应先写清速率表示物质，之后才能稳定迁移。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
