insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H2_EQUIL','H2_EQUIL','化学平衡移动','先判断瞬间Q与K或正逆速率，再判断平衡移动方向。','用勒夏特列原理处理浓度、压强、温度变化，并区分瞬间变化与新平衡。','["写平衡关系","判断条件改变瞬间影响","比较Q与K或正逆速率","给出移动与新值"]'::jsonb,'["把催化剂说成使平衡移动","把恒容加惰气当成压强效应"]'::jsonb,'催化剂同等加快正逆反应，不改变平衡组成。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
