insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H2_K','H2_K','平衡常数与转化率计算','K只由温度决定；表格计算必须把起始、变化、平衡三行对应起来。','用三段式、K表达式、Q与K比较和转化率完成定量平衡。','["列起始量","按计量数设变化量","写平衡量","代入K并验根"]'::jsonb,'["把固体写入K表达式","同温度下因浓度改变而改变K"]'::jsonb,'纯固体和纯液体通常不写入平衡常数表达式。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
