insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H2_K_02','M4W_H2_K_2','H2_K',2,'高二','反应CaCO₃(s)⇌CaO(s)+CO₂(g)的Kc表达式为','["c(CaO)c(CO₂)/c(CaCO₃)","c(CO₂)","1/c(CO₂)","c(CaCO₃)/c(CaO)"]'::jsonb,1,'纯固体不写入表达式。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
