insert into public.chem_questions(id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind) values('Q4W_H3_STOICH_05','M4W_H3_STOICH_5','H3_STOICH',3,'高三','关于“化学计量与阿伏加德罗常数”的核心规律，下列说法正确的是','["先定对象和条件，再以物质的量为枢纽做守恒与换算。","忽略分子内部原子数","标准状况对象不是气体","题目条件不会影响判断"]'::jsonb,0,'该模块的核心规律是：先定对象和条件，再以物质的量为枢纽做守恒与换算。','先确定考查对象，再逐项用定义、守恒或平衡关系核对。','approved','IN','teacher_original') on conflict(id) do update set skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',updated_at=now();
