insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H3_ION_REDOX','H3_ION_REDOX','离子反应与氧化还原综合','复杂反应仍然服从反应事实、电子守恒、电荷守恒和原子守恒。','综合离子共存、离子方程式正误、少量过量、陌生氧化还原配平。','["识别反应事实","判断少量过量","做电子守恒","做电荷原子复核"]'::jsonb,'["忽略氧化还原先后顺序","只看是否能反应不看用量"]'::jsonb,'酸性KMnO₄氧化Fe²⁺时MnO₄⁻与Fe²⁺按1∶5反应。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
