insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H3_INORGANIC','H3_INORGANIC','元素化合物与无机转化','用价态、类别和条件构建元素转化网络。','整合Na、Al、Fe、Cl、S、N等常见元素及其化合物性质、制备和检验。','["确定中心元素价态","识别酸碱或氧化还原性质","结合条件判断产物","写方程式并验证"]'::jsonb,'["把两性理解为任意条件都能反应","忽略浓度温度对产物的影响"]'::jsonb,'Al(OH)₃既能与强酸反应，也能与强碱反应。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
