insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H3_EXPERIMENT','H3_EXPERIMENT','化学实验综合','实验设计必须形成“目的—操作—现象—结论—误差”闭环。','覆盖制备、净化、检验、定量、探究、控制变量、装置评价和安全。','["写清实验目的","控制变量与干扰","记录可观察现象","结论不超出证据","分析误差方向"]'::jsonb,'["结论大于证据范围","洗气瓶进出气方向错误"]'::jsonb,'验证某因素影响时，除该因素外其余条件应尽量相同。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
