insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H3_PROCESS','H3_PROCESS','无机工艺流程','流程图的每一步都要回答“目标物去哪、杂质去哪、条件为何”。','综合浸取、氧化还原、调pH、沉淀、过滤、洗涤、结晶、循环利用和产率。','["标目标元素流向","识别每步目的","用平衡和氧化还原解释条件","检查产品纯度与环保"]'::jsonb,'["只写操作名不写目的","忽略滤渣或母液中的目标元素损失"]'::jsonb,'洗涤沉淀的目的是除去表面吸附的可溶性杂质。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
