insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H3_STRUCTURE','H3_STRUCTURE','物质结构与性质','结构层级决定性质：电子排布—成键—空间构型—作用力—宏观性质。','覆盖核外电子、周期性、化学键、分子构型、杂化、晶体类型和性质比较。','["确定微粒电子结构","判断成键与构型","识别晶体类型","联系熔沸点与导电性"]'::jsonb,'["把分子间作用力当化学键","只按相对分子质量比较熔沸点"]'::jsonb,'离子晶体熔融后离子可自由移动，通常能导电。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
