insert into public.chem_knowledge_cards(id,skill_id,title,core,detail,steps,common_mistakes,micro_example,review_status) values('KC_H3_ORGANIC','H3_ORGANIC','有机化学基础','官能团决定主要反应类型，碳骨架决定同分异构。','覆盖烃、卤代烃、醇、酚、醛、酸、酯、反应类型、合成路线和同分异构。','["识别官能团","判断反应类型","跟踪碳骨架变化","用条件筛选同分异构体"]'::jsonb,'["把取代和加成混淆","漏看官能团数量与位置限制"]'::jsonb,'乙醇氧化可生成乙醛，继续氧化可生成乙酸。','approved') on conflict(id) do update set title=excluded.title,core=excluded.core,detail=excluded.detail,steps=excluded.steps,common_mistakes=excluded.common_mistakes,micro_example=excluded.micro_example,review_status='approved',updated_at=now();
